(() => {const R=window.PODCAST_RESTORE,D=window.PODCAST_WEB,K=window.KONTEXTIA;if(!D||!K)return;
D.audio_v2=R.folgen;D.lesefassungen=R.lesefassungen;D.direkte_stimmen=[...D.direkte_stimmen.filter(x=>x.figur!=='kessa'),...R.direkte_stimmen];
for(const [id,name,role] of [['ada-adam','Ada Adam','Adam-Optimierer · Ahnengalerie'],['frieda-zweiunddreissig','Frieda Zweiunddreißig','FP32 · Ahnengalerie'],['bruni-brainfloat','Bruni Brainfloat','bfloat16 · Ahnengalerie']])D.figuren[id]={id,name,rolle:role,bild:'assets/ahnen/'+id+'.svg',farbe:'#d8bb87',bildbeleg:'[DE] Namensmedaillon der Ahnenrolle, kein erfundenes Figurenporträt'};
D.hinweis='Die Erzählerin und die Bewohner nehmen dich mit durch Kontextia.';
K.hoerspiel.folgen=[...R.folgen,...K.hoerspiel.folgen.filter(x=>x.art==='liste')];
for(const intro of R.direkte_stimmen){for(const list of K.hoerspiel.folgen.filter(x=>x.art==='liste')){const entry=list.eintraege.find(x=>x.figur===intro.figur);if(entry)Object.assign(entry,intro);}for(const collection of [K.figuren,window.PREMIUM?.figuren]){if(Array.isArray(collection)){const f=collection.find(x=>x.id===intro.figur);if(f){f.stimme=intro.datei;f.audio=intro.datei;}}}}
function override(data){if(!data?.lines)return data;for(const line of data.lines)for(const seg of line.segments){const o=R.dialog_ersatz.find(x=>x.raw===line.raw&&x.old_text===seg.text);if(o){Object.assign(seg,{audio:o.audio,duration:o.duration,label:o.label,figur:o.figur});delete seg.interpretation;}}return data;}
let dialogue=override(window.WEB_DIALOGUE_AUDIO);Object.defineProperty(window,'WEB_DIALOGUE_AUDIO',{configurable:true,enumerable:true,get:()=>dialogue,set:value=>{dialogue=override(value);}});
})();
(() => {function residents(){if(!Array.isArray(window.MapResidentData))return;const k=MapResidentData.find(x=>x.id==='kessa');if(k)k.audio=PODCAST_RESTORE.direkte_stimmen[0].datei;}residents();document.addEventListener('DOMContentLoaded',residents);})();
